'use strict';
// Складання: копіює src/ у build/app/ і створює виконувані файли
// build/hello (Linux/macOS) та build/hello.cmd (Windows).
// Повторний запуск перезаписує лише файли у build/, нічого не видаляє.

const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const srcDir = path.join(root, 'src');
const buildDir = path.join(root, 'build');
const appDir = path.join(buildDir, 'app');

function fail(message) {
  console.error(`[build] ERROR: ${message}`);
  process.exit(1);
}

if (!fs.existsSync(srcDir)) fail('src/ not found. Run /create-project first.');

const sources = fs.readdirSync(srcDir).filter((f) => f.endsWith('.js'));
if (!sources.includes('index.js')) fail('src/index.js not found.');

fs.mkdirSync(appDir, { recursive: true });
for (const file of sources) {
  fs.copyFileSync(path.join(srcDir, file), path.join(appDir, file));
}

const unixLauncher = [
  '#!/bin/sh',
  '# Generated by scripts/build.js',
  'DIR="$(cd "$(dirname "$0")" && pwd)"',
  'exec node "$DIR/app/index.js" "$@"',
  '',
].join('\n');
const unixPath = path.join(buildDir, 'hello');
fs.writeFileSync(unixPath, unixLauncher);
fs.chmodSync(unixPath, 0o755);

const winLauncher = [
  '@echo off',
  'rem Generated by scripts/build.js',
  'node "%~dp0app\\index.js" %*',
  '',
].join('\r\n');
fs.writeFileSync(path.join(buildDir, 'hello.cmd'), winLauncher);

const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'));
const info = {
  name: pkg.name,
  version: pkg.version,
  node: process.version,
  platform: process.platform,
  arch: process.arch,
  builtAt: new Date().toISOString(),
};
fs.writeFileSync(path.join(buildDir, 'build-info.json'), JSON.stringify(info, null, 2) + '\n');

console.log(`[build] copied ${sources.length} source file(s) to build/app/`);
console.log('[build] executables: build/hello, build/hello.cmd');
console.log(`[build] OK (${info.platform}/${info.arch}, node ${info.node})`);
